-- Data sekolah SMA & SMK se-Pulau Jawa (id, lintang, bujur dihapus)

CREATE TABLE `sekolah` (
  `kode_prop` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `propinsi` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `kode_kab_kota` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `kabupaten_kota` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `kode_kec` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `kecamatan` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `npsn` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `sekolah` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `bentuk` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `alamat_jalan` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;



















































